const read = path => readFileSync(path, 'utf8');
const config = JSON.parse(read('capacitor.config.json'));
const url = new URL(config.server.url);
if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash) throw Error('Use a plain HTTPS app URL');
const swift = read('native/NativeShell.swift').replace('__APP_URL__', JSON.stringify(url.href));
const delegatePath = 'ios/App/App/AppDelegate.swift';
const start = '// BEGIN FACTORY NATIVE SHELL';
const end = '// END FACTORY NATIVE SHELL';
let delegate = read(delegatePath);
const index = delegate.indexOf(start);
if (index !== -1) {
  const finish = delegate.indexOf(end, index);
  if (finish === -1) throw Error('Incomplete generated block; inspect AppDelegate.swift');
  delegate = delegate.slice(0, index) + delegate.slice(finish + end.length);
}
// Already compiled source: no manual Xcode source registration needed.
writeFileSync(delegatePath, delegate.trimEnd() + '\\n\\n' + start + '\\n' + swift + '\\n' + end + '\\n');
const storyboard = 'ios/App/App/Base.lproj/Main.storyboard';
let xml = read(storyboard);
if (!/customClass="(?:CAPBridgeViewController|NativeShellViewController)"/.test(xml)) throw Error('Unexpected storyboard controller');
xml = xml.replace(/customClass="(?:CAPBridgeViewController|NativeShellViewController)"(?: customModule="[^"]*")?(?: customModuleProvider="[^"]*")?/, 'customClass="NativeShellViewController" customModule="App" customModuleProvider="target"');
writeFileSync(storyboard, xml);
const project = 'ios/App/App.xcodeproj/project.pbxproj';
const pbx = read(project);
if (!pbx.includes('IPHONEOS_DEPLOYMENT_TARGET =')) throw Error('Deployment target missing');
writeFileSync(project, pbx.replace(/IPHONEOS_DEPLOYMENT_TARGET = [^;]+;/g, 'IPHONEOS_DEPLOYMENT_TARGET = 18.7.8;'));
console.log('Configured shell. Run npx cap sync ios and open Xcode to select your signing team.');
